import { textarea, select, checkbox, htmlEscape } from "../tool-core.js";export default {form: `<div class="field-grid">${textarea({ id: "rmCsv", label: "Redirect map (CSV)", help: "One redirect per line. Format: old_url,new_url,status. Status defaults to 301 if omitted.", value: "/old-page, /new-page, 301\n/blog/2024/post, /blog/post, 301\n/contact-us, /contact, 301" })}</div><div class="field-grid">${select({ id: "rmFormat", label: "Output format", options: [{label:"Netlify _redirects",value:"netlify"},{label:"Netlify netlify.toml",value:"netlify-toml"},{label:"Vercel vercel.json",value:"vercel"},{label:"Apache .htaccess",value:"apache"},{label:"Nginx config",value:"nginx"}], value: "netlify" })}${checkbox({ id: "rmNormalize", label: "Normalize trailing slashes", checked: true })}</div><div class="field-grid">${checkbox({ id: "rmValidate", label: "Check for duplicates and loops", checked: true })}</div>`,generate(root) {const raw = root.querySelector("#rmCsv").value.trim();const format = root.querySelector("#rmFormat").value;const normalize = root.querySelector("#rmNormalize").checked;const validate = root.querySelector("#rmValidate").checked;if (!raw) {return { output: "Enter redirect mappings in CSV format: old_url,new_url,status (one per line)." };}const redirects = [];const parseErrors = [];raw.split("\n").forEach((line, i) => {const ln = i + 1;const trimmed = line.trim();if (!trimmed || trimmed.startsWith("#")) return;const parts = trimmed.split(",").map(s => s.trim());if (parts.length < 2) {parseErrors.push(`Line ${ln}: Expected "old_url,new_url" — got "${trimmed.substring(0, 60)}"`);return;}let status = "301";if (parts.length >= 3 && /^\d{3}$/.test(parts[2])) status = parts[2];redirects.push({ from: parts[0], to: parts[1], status, line: ln });});if (parseErrors.length) {return { output: parseErrors.join("\n") + "\n\nFix the CSV formatting errors before converting." };}if (!redirects.length) {return { output: "No valid redirect mappings found. Each line needs: old_url,new_url (status optional, defaults to 301)." };}const warnings = [];if (validate) {const froms = {};redirects.forEach(r => {if (!froms[r.from]) froms[r.from] = [];froms[r.from].push(r);});Object.entries(froms).forEach(([from, list]) => {if (list.length > 1) {warnings.push(`Duplicate source: "${from}" has ${list.length} redirects (lines ${list.map(r => r.line).join(", ")}). Only the last one applies.`);}});const fromSet = new Set(redirects.map(r => r.from));redirects.forEach(r => {if (fromSet.has(r.to)) {warnings.push(`Potential chain: "${r.from}" → "${r.to}". "${r.to}" is also a redirect source. Verify this is intended, not a loop.`);}});}if (normalize) {redirects.forEach(r => {if (!r.from.endsWith("/") && !r.from.includes(".") && !r.from.includes("?")) {}});}const lines = [];if (warnings.length) {lines.push("# === Warnings ===", ...warnings.map(w => `# ${w}`), "");}switch (format) {case "netlify":redirects.forEach(r => lines.push(`${r.from} ${r.to} ${r.status}`));lines.push("", "# Save as: _redirects (in site publish root)");lines.push("# Netlify docs: https://docs.netlify.com/routing/redirects/");break;case "netlify-toml":lines.push("[[redirects]]");redirects.forEach(r => {lines.push(` from = "${r.from}"`);lines.push(` to = "${r.to}"`);lines.push(` status = ${r.status}`);if (r !== redirects[redirects.length - 1]) {lines.push("", "[[redirects]]");}});lines.push("", "# Save as: netlify.toml (in repository root)");break;case "vercel":lines.push("{");lines.push(' "redirects": [');redirects.forEach((r, i) => {lines.push(` { "source": "${r.from}", "destination": "${r.to}", "permanent": ${r.status === "301" ? "true" : "false"} }${i < redirects.length - 1 ? "," : ""}`);});lines.push(" ]");lines.push("}");lines.push("", "# Save as: vercel.json (in repository root)");break;case "apache":redirects.forEach(r => {const code = r.status === "301" ? "permanent" : "temp";lines.push(`Redirect ${code} ${r.from} ${r.to}`);});lines.push("", "# Save as: .htaccess (in site root)");lines.push("# Requires mod_alias enabled.");break;case "nginx":redirects.forEach(r => {const perm = r.status === "301" ? "permanent" : "redirect";lines.push(`rewrite ^${r.from.replace(/\./g, "\\.")}$ ${r.to} ${perm};`);});lines.push("", "# Add to server or location block in nginx.conf");break;}return { output: lines.join("\n") };}};